def insert(t, x):
    if t is None:
        return {'v': x, 'l': None, 'r': None}
    if x < t['v']: t['l'] = insert(t['l'], x)
    else: t['r'] = insert(t['r'], x)
    return t
t = None
for x in [5, 3, 8, 4]:
    t = insert(t, x)
print(t['l']['r']['v'])

import heapq
def kth_largest(nums, k):
    h = []
    for x in nums:
        heapq.heappush(h, x)
        if len(h) > k:
            heapq.heappop(h)
    return h[0]
print(kth_largest([3, 1, 7, 5, 8], 2))

def ok(n, lo, hi):
    if n is None: return True
    if not (lo < n['v'] < hi): return False
    return ok(n['l'], lo, n['v']) and ok(n['r'], n['v'], hi)
t = {'v': 10,
     'l': {'v': 5, 'l': None, 'r': {'v': 12, 'l': None, 'r': None}},
     'r': {'v': 15, 'l': None, 'r': None}}
print(ok(t, float('-inf'), float('inf')))
